+/** Records the completed data-changing request without storing its secret. */
+export function recordAudit(store, { time, name, method, path, status }) {
+  store.data.audit.push({ time, name, method, path, status });
+}
+
+/** Lists audit entries newest first, including requests with equal timestamps. */
+export function listAudit(store) {
+  return store.data.audit.slice().reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
