diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..b81bd8d
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,79 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { fresh, NOW, seed } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}-key` });
+
+test("missing and unknown keys are unauthorized; roles fail closed", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Bearer unknown", "Basic seed-manager-key", "Bearer "]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+    assert.equal(typeof response.body.error.message, "string");
+  }
+  for (const role of ["viewer", "cook", "manager"]) {
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+    assert.equal((await handle({ path: "/audit", headers: headers(role) })).status, role === "manager" ? 200 : 403);
+  }
+  const denied = await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("viewer"), body: { portions: 4 } });
+  assert.equal(denied.status, 403);
+  assert.equal(denied.body.error.code, "forbidden");
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("cooks can perform only the four permitted writes", async () => {
+  const handle = createApp(fresh());
+  const manager = headers("manager");
+  const cook = headers("cook");
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } });
+  for (const [path, body] of [
+    ["/recipes/1/cook", { portions: 4 }],
+    ["/batches/1/waste", { qty: 0.1 }],
+    ["/temperatures", { location: "fridge", celsius: 4 }],
+    [`/stocktakes/${take.body.id}/counts`, { batchId: 6, counted: 12 }],
+  ]) {
+    const response = await handle({ method: "POST", path, body, headers: cook });
+    assert.ok(response.status < 300, JSON.stringify(response));
+  }
+  for (const [method, path] of [
+    ["POST", "/orders"], ["POST", "/prices"], ["POST", "/dishes"],
+    ["POST", "/stocktakes"], ["POST", `/stocktakes/${take.body.id}/finish`],
+    ["PUT", "/items/1/allergens"], ["POST", "/import/items"],
+    ["POST", "/jobs/nightly"], ["POST", "/outbox/1/sent"],
+  ]) {
+    assert.equal((await handle({ method, path, headers: cook })).status, 403);
+  }
+});
+
+test("audit saves once with the change, survives reopening, and sorts newest first", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-audit-"));
+  try {
+    const file = join(dir, "db.json");
+    writeFileSync(file, JSON.stringify(seed()));
+    const store = openStore(file);
+    let saves = 0;
+    const save = store.save.bind(store);
+    store.save = () => { saves++; save(); };
+    const handle = createApp(store, { clock: () => NOW });
+    for (const celsius of [3, 4]) {
+      assert.equal((await handle({ method: "POST", path: `/temperatures?reading=${celsius}`, headers: headers("cook"), body: { location: "fridge", celsius } })).status, 201);
+    }
+    await handle({ method: "POST", path: "/temperatures", headers: headers("cook"), body: {} });
+    await handle({ path: "/items", headers: headers("viewer") });
+    assert.equal(saves, 2);
+    const reopened = openStore(file);
+    const response = await createApp(reopened)({ path: "/audit", headers: headers("manager") });
+    assert.deepEqual(response.body.map((entry) => entry.path), ["/temperatures?reading=4", "/temperatures?reading=3"]);
+    assert.deepEqual(response.body[0], { time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: "/temperatures?reading=4", status: 201 });
+    assert.equal(JSON.parse(readFileSync(file, "utf8")).temperatures.length, seed().temperatures.length + 2);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
